-- Fonte: rate sheet 0901.xlsx | importado em 2026-09-01T09:18:32
set search_path to mcat, public;
begin;

-- Portos (UN/LOCODE)

-- Armadores

-- Rate sheet (idempotente por source_file + issued_on)

do $$
declare
  v_sheet uuid;
  v_route uuid;
begin
  select id into v_sheet from mcat.rate_sheets where source_file = 'rate sheet 0901.xlsx' and issued_on is not distinct from '2026-09-01';
  delete from mcat.freight_routes where rate_sheet_id = v_sheet;
  delete from mcat.rate_issues where rate_sheet_id = v_sheet;

end $$;

commit;
